window.REPORT_PRELOAD_CACHE["META.html"] = {"version":"96bcdd4884832dd8ae889cdda2abea779cbb81fc8cf15799997494f518e3966a","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Meta Platforms (NASDAQ: META) 深度研究报告：从全球社交广告帝国到 Llama 开源生态与 AI 超级智能变现核心引擎</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#070B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            metablue: {\n              400: '#38BDF8',\n              500: '#0668E1',\n              600: '#0051B8',\n            },\n            accent: {\n              500: '#3B82F6',\n              600: '#2563EB',\n            },\n            teal: {\n              500: '#06B6D4',\n              600: '#0891B2',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微光 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(6, 104, 225, 0.28) 0%, rgba(56, 189, 248, 0.08) 100%);\n      border-left: 3px solid #38BDF8;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-metablue-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-metablue-500 via-sky-400 to-teal-400 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-metablue-500 to-sky-400 flex items-center justify-center font-extrabold text-white shadow\">\n        MT\n      </div>\n      <div>\n        <div class=\"text-[11px] text-metablue-400 font-semibold tracking-wider uppercase\">NASDAQ: META · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">Meta Platforms 深度研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">META 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n          <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球互联网媒体与 AI 应用变现研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (FY25 / FY26E / FY27E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-metablue-500 to-sky-400 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-metablue-500/30\">\n            META\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-metablue-400 bg-metablue-500/15 px-2 py-0.5 rounded\">NASDAQ: META</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">Meta 深度研究报告</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          35.4亿日活社交矩阵 · AI 推荐变现引擎与智能穿戴/开源大模型生态领航者\n        </p>\n      </div>\n\n      <!-- 股票实时快照徽章 -->\n      <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">FY26E 营收共识</span>\n          <span class=\"font-mono font-bold text-white\">~$246.5B <span class=\"text-metablue-400\">(+22.6%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">FY27E 营收共识</span>\n          <span class=\"font-mono font-bold text-teal-400\">~$292.0B <span class=\"text-slate-400\">(+18.5%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">远期估值锚</span>\n          <span class=\"font-mono font-bold text-metablue-400\">~21.5x P/E · 营业利润率 42%+</span>\n        </div>\n      </div>\n\n      <!-- 六个核心章节目录导航 -->\n      <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-metablue-400 mr-2\">00</span>执行摘要与核心指标</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n          </a>\n          <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-metablue-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-metablue-500 hover:bg-metablue-600 text-white text-xs font-extrabold transition shadow-sm\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. Hero 研报封面区与执行摘要\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <!-- 顶部研报元数据标签栏 -->\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-metablue-500/15 text-metablue-600 dark:text-metablue-400 font-bold border border-metablue-500/30\">评级：买入 / 核心超配 (Outperform)</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–FY2027 AI 变现收获与端侧硬件破局期</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖时间：2026年11月</span>\n            <span>NASDAQ: META</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-slate-900 to-[#061A3A] text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <!-- 背景科技蓝神经网络点阵纹理 -->\n          <div class=\"absolute inset-0 opacity-15 pointer-events-none\" style=\"background-image: radial-gradient(#38BDF8 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-metablue-500/20 border border-metablue-400/40 text-metablue-400 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-metablue-400 animate-pulse\"></span>\n              <span>CORE THESIS · 全球唯一将千亿级 AI 算力 CapEx 直接转化为广告 ROI 提效的超级应用帝国</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              Meta Platforms (NASDAQ: META) 深度研究报告：从全球社交广告帝国到 Llama 开源生态与 AI 超级智能变现核心引擎\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              依托全球超过 <strong class=\"text-metablue-400\">35.4 亿家族日活跃用户（DAP）</strong>的无可替代社交图谱，Meta 凭借全栈自研 <strong class=\"text-white\">Andromeda / GEM 统一大模型推荐系统</strong>与 <strong class=\"text-sky-300\">Advantage+ AI 广告自动化套件</strong>，成功在两千亿美元体量上维持 <strong class=\"text-metablue-400\">20%+ 营收增速</strong>（FY26E 营收共识达 <strong class=\"text-white\">~$246.5B</strong>）。\n              与此同时，Meta AI 助手月活突破 <strong class=\"text-teal-400\">10 亿大关</strong>，WhatsApp 商业消息与 Threads 商业化加速放量，叠加 <strong class=\"text-sky-300\">Ray-Ban Meta / Orion 智能眼镜</strong>打开下一代人机交互入口，使千亿美元级基础设施资本开支（FY26 CapEx ~$125B）具备清晰可验证的高 ROI 商业闭环。\n            </p>\n\n            <!-- 核心投资结论高亮条 -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">AI 广告飞轮“量价齐升”</div>\n                <div class=\"text-white font-semibold\">GEM 大模型驱动 Facebook/Instagram 用户时长与广告转化率双位数跃升</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">第二增长曲线全面接棒</div>\n                <div class=\"text-metablue-400 font-semibold\">WhatsApp 商业化、Threads 广告与 Meta AI 10亿月活打开千亿级增量空间</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">AI 眼镜定义下一代端侧入口</div>\n                <div class=\"text-teal-400 font-semibold\">Ray-Ban Meta 智能眼镜年销量破千万副，成为多模态 AI 最佳物理载体</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <!-- KPI 1 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>FY2026E 全年总营收</span>\n              <span class=\"p-1.5 rounded-lg bg-metablue-500/15 text-metablue-600 dark:text-metablue-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$246.5B</span>\n              <span class=\"text-xs font-bold text-metablue-600 dark:text-metablue-400 bg-metablue-500/15 px-2 py-0.5 rounded\">+22.6% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              继 FY25 突破 $201.0B 后延续 22%+ 强劲扩张，广告展示量与单价（CPM）实现双轮驱动。\n            </p>\n          </div>\n\n          <!-- KPI 2 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>家族日活跃用户 (DAP)</span>\n              <span class=\"p-1.5 rounded-lg bg-sky-500/10 text-sky-600 dark:text-sky-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">35.4亿</span>\n              <span class=\"text-xs font-bold text-sky-600 dark:text-sky-400 bg-sky-500/10 px-2 py-0.5 rounded\">+6.0% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              覆盖全球超 43% 人口；Threads 月活突破 3.5 亿，Meta AI 助手月活突破 10 亿大关。\n            </p>\n          </div>\n\n          <!-- KPI 3 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>营业利润率 & 经营现金流</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">42.8%</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">OCF $118B+</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              尽管算力折旧攀升，AI 提效与高毛利广告使营业利润突破 $105B，内部现金流完全覆盖千亿 CapEx。\n            </p>\n          </div>\n\n          <!-- KPI 4 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>FY2027E 预期 & 远期估值</span>\n              <span class=\"p-1.5 rounded-lg bg-indigo-500/10 text-indigo-600 dark:text-indigo-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$292B</span>\n              <span class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 bg-indigo-500/10 px-2 py-0.5 rounded\">Fwd P/E ~21.5x</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              低于纳斯达克 100 科技龙头均值，且拥有全球最强的消费级 AI 变现确定性，估值安全边际充足。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-metablue-600 dark:text-metablue-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：AI 驱动的超级应用矩阵 + 端侧智能硬件双轮驱动</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2026E 总营收 ~$246.5B · 应用家族广告占比 ~97.2%</span>\n        </div>\n\n        <!-- 交互式 Chart.js 双视图切换面板 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 左侧：双视图图表 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2022–FY2027E 分部营收演进与广告复利加速</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">应用家族营收从 $114.5B 跃升至 FY26E $242.5B，Reality Labs 在 AI 眼镜带动下重回高增</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-metablue-600 dark:text-metablue-400 shadow-sm transition\">视图A：营收演进</button>\n                <button onclick=\"switchBizChart('foa_split')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：区域与产品拆解</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"bizArchitectureChart\"></canvas>\n            </div>\n          </div>\n\n          <!-- 右侧：结构性拆解核心洞察 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性增长引擎</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-metablue-500/15 text-metablue-600 dark:text-metablue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">GEM 统一大模型重构推荐与广告转化</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      自研生成式广告推荐模型（GEM）与 Andromeda 检索架构全面替代传统小模型，使 Reels 观看时长与广告点击转化率（CVR）双位数提升，<strong>Advantage+ 自动化广告年化流水突破 $60B+</strong>。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">WhatsApp 商业消息与 Threads 货币化提速</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      Click-to-WhatsApp 广告及企业 AI 客服代理（Business AI Agents）在拉美、亚太与欧美中小商户快速渗透，<strong>应用家族“其他非广告收入”同比暴增 50%+</strong>。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">AI 智能眼镜引爆端侧硬件破局</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      联合依视路陆逊梯卡推出的 <strong>Ray-Ban Meta / Oakley Meta 智能眼镜</strong>供不应求，搭配轻量化光波导显示版，确立 Meta 在下一代“无屏/轻显示端侧 AI 入口”的全球绝对领先地位。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">核心商业化催化剂</span>\n              <span class=\"font-bold text-metablue-600 dark:text-metablue-400\">GEM 大模型全面部署 & Threads 全球广告放量</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 五大核心业务板块详细卡片矩阵 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <!-- 板块 1：核心社交与短视频广告矩阵 (占两列宽度以突出核心地位) -->\n          <div class=\"md:col-span-2 report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-metablue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n              <div class=\"flex items-center space-x-2\">\n                <span class=\"px-2.5 py-1 rounded-md bg-metablue-500/15 text-metablue-600 dark:text-metablue-400 text-xs font-bold\">核心现金牛 · 占比 ~97.2%</span>\n                <span class=\"font-mono text-xs font-bold text-sky-600 dark:text-sky-400\">+22.4% YoY</span>\n              </div>\n              <span class=\"text-base font-extrabold font-mono text-slate-900 dark:text-white\">FY26E 营收：~$239.5B</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 应用家族数字广告（Instagram + Facebook + Reels + Threads）</h3>\n            <div class=\"mt-3 grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">流量与时长引擎：Instagram & Reels</div>\n                <p class=\"leading-relaxed\">\n                  Instagram 全球月活超 25 亿，<strong>Reels 短视频日播放量突破 2,200 亿次</strong>。AI 跨平台推荐使未关注账号的优质内容分发占比超 50%，带动广告展示量（Ad Impressions）保持 12%+ 稳健增长。\n                </p>\n              </div>\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">广告主 ROI 工具：Advantage+ 全自动投放</div>\n                <p class=\"leading-relaxed\">\n                  集成生成式 AI 素材扩展、自动受众寻优与跨渠道归因，使广告主单次获客成本（CPA）平均下降 18%–22%，推动单条广告均价（Price per Ad）持续同比正增长 10%+。\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- 板块 2：WhatsApp 商业通信与 AI 客服代理 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">高增第二曲线 · +52% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$3.0B+ (非广告)</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. WhatsApp 商业消息与 AI 代理</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                全球月活超 30 亿。结合 Click-to-WhatsApp 引流广告（年化流水超 $15B）与付费商业 API、AI 导购对话机器人，正快速复制亚洲超级应用的商业闭环模式。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold\">\n              全球 30亿月活 · 企业 AI 客服商业化爆发\n            </div>\n          </div>\n\n          <!-- 板块 3：Meta AI 与 Llama 开源生态 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">10亿月活 · 开源标准制定者</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">Llama 4 旗舰矩阵</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. Meta AI 助手与 Llama 开源大模型</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                原生嵌入 WhatsApp、Instagram、Facebook 与 Messenger 搜索框，月活突破 10 亿。通过开源 <strong>Llama 4</strong> 建立全球开发者标准，倒逼云计算巨头共同分担模型优化与推理生态成本。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n              10亿 MAU · 全球下载量破 12 亿次\n            </div>\n          </div>\n\n          <!-- 板块 4：Reality Labs 智能眼镜与 XR -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">占比 ~1.6% · +45% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">FY26E ~$4.0B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. Reality Labs（AI 眼镜 + Quest + Orion）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                <strong>Ray-Ban Meta 智能眼镜</strong>凭借第一视角多模态视觉识别与实时翻译成为现象级爆款，联合 Oakley 等品牌矩阵放量，摆脱手机操作系统底层限制，抢占下一代个人计算平台制高点。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n              智能眼镜市占率 &gt;70% · 下一代端侧入口\n            </div>\n          </div>\n\n          <!-- 板块 5：Threads 实时社交与创作者经济 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-sky-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-sky-500/10 text-sky-600 dark:text-sky-400 text-xs font-bold\">3.5亿+ MAU · 商业化元年</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">增量广告池</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">5. Threads 公共对话与实时信息流</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                全球月活突破 3.5 亿、日活破亿，已全面向全球品牌广告主开放信息流广告投放。凭借与 Instagram 账号体系无缝互通，成为品牌实时热点营销的核心新阵地。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n              对标 X (Twitter) · 零边际获客成本扩张\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 行业地位与四重核心护城河 (Industry Position & Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：35亿人社交图谱 + AI 算法双轮壁垒</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球数字效果广告双寡头之一)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：四重护城河深度解析 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 护城河 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-metablue-500/15 text-metablue-600 dark:text-metablue-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">35.4 亿日活真实社交关系图谱</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                跨 Facebook、Instagram、WhatsApp、Messenger 构建人类历史上最庞大的真实社交与兴趣关系网络，强双边网络效应锁定用户社交关系链与高切换成本，新入局者几乎无法从零重建同量级关系网络。\n              </p>\n            </div>\n\n            <!-- 护城河 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-sky-500/15 text-sky-600 dark:text-sky-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">第一方闭环数据 + GEM 推荐飞轮</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                在苹果 ATT 隐私新政后，Meta 投入数百亿美元重构底层 AI 算力集群（超 130 万颗等效 H100/Blackwell 算力），利用万亿级站内行为信号训练 <strong>GEM 统一推荐模型</strong>，实现“越用越懂你 → 转化率越高 → 广告主预算越集中”的正向飞轮。\n              </p>\n            </div>\n\n            <!-- 护城河 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Llama 开源生态反制闭源模型壁垒</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                通过开源 <strong>Llama 系列大模型</strong>将基础模型能力“商品化”，有效防止 OpenAI、Anthropic 或 Google 通过闭源模型垄断 AI 入口并向 Meta 征收“模型税”，同时吸引全球开发者共建高效推理工具链反哺内部算力效率。\n              </p>\n            </div>\n\n            <!-- 护城河 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">千万级广告主长尾生态与端侧硬件卡位</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                全球超 <strong>1,000 万家活跃中小广告主</strong>高度依赖 Meta 进行低门槛、高 ROAS（广告支出回报率）获客，单一客户占比极低；叠加 Ray-Ban Meta 智能眼镜提前卡位下一代 AI 硬件终端。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：五维护城河雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">数字广告与消费级 AI 五维护城河量化雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Meta Platforms vs Alphabet (Google) vs TikTok / Snap（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 同行竞争格局横向对比 (Competitive Landscape)\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-metablue-600 dark:text-metablue-400\">Section 03 · Global Competitive Landscape</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：效果广告双寡头统治，社交视频份额持续回流</h2>\n          </div>\n          <!-- 交互式筛选按钮 -->\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-metablue-500 text-white shadow-sm transition\">全部阵营</button>\n            <button onclick=\"filterCompetitors('ad_giant')\" data-filter=\"ad_giant\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">数字广告巨头</button>\n            <button onclick=\"filterCompetitors('social')\" data-filter=\"social\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">社交与短视频竞品</button>\n            <button onclick=\"filterCompetitors('ai_model')\" data-filter=\"ai_model\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">消费级 AI 助手竞争</button>\n          </div>\n        </div>\n\n        <!-- 横向对比矩阵表格 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心平台</th>\n                  <th class=\"py-4 px-4 min-w-[130px]\">全球活跃用户体量</th>\n                  <th class=\"py-4 px-4 min-w-[140px]\">AI 推荐与变现引擎</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">全球数字广告份额</th>\n                  <th class=\"py-4 px-4 min-w-[115px]\">营业利润率</th>\n                  <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞合关系评估</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <!-- 行 1：Meta 基准 -->\n                <tr data-category=\"core\" class=\"bg-metablue-500/5 dark:bg-metablue-500/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-metablue-500 text-white text-[10px] font-extrabold\">核心基准</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">Meta Platforms (META)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">IG / FB / WhatsApp / Threads / Llama</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-sky-500/15 text-sky-700 dark:text-sky-400\">35.4亿 DAP · 10亿 AI MAU</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">GEM 大模型 + Advantage+</td>\n                  <td class=\"py-4 px-4 font-bold text-metablue-600 dark:text-metablue-400\">~22%–24% (社交霸主)</td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~42.8%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>社交效果广告绝对统治者：</strong>“发现式推荐（Discovery Engine）”精准捕捉用户潜在消费意图，无需依赖搜索关键词即可高效转化，ROAS 领先全行业。\n                  </td>\n                </tr>\n\n                <!-- 行 2：Alphabet (Google / YouTube) -->\n                <tr data-category=\"ad_giant\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Alphabet (Google / YouTube)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Search / YouTube Shorts / Gemini</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">25亿+ 月活 · 搜索垄断</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Performance Max + AI Overviews</td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">~27%–29% (全球第一)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~32%–34%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>搜索意图霸主但面临 AI 分流：</strong>在主动搜索与长视频（YouTube）占优，但传统搜索链接正面临 ChatGPT/Perplexity 与 AI 摘要分流，而 Meta 社交沉浸场景抗 AI 替代性更强。\n                  </td>\n                </tr>\n\n                <!-- 行 3：Amazon Ads -->\n                <tr data-category=\"ad_giant\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Amazon Ads (亚马逊广告)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Retail Media + Prime Video 广告</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">3亿+ 高净值购物活跃户</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">零售交易闭环归因算法</td>\n                  <td class=\"py-4 px-4 font-semibold text-amber-600 dark:text-amber-400\">~8%–9% (零售媒体第一)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">零售业务整体 ~11%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>交易转化闭环极强但流量上限明确：</strong>聚焦站内货架与流媒体，Meta 则占据用户日均数小时高频社交通信时间，二者在品牌种草与独立站电商投放上形成互补与竞合。\n                  </td>\n                </tr>\n\n                <!-- 行 4：ByteDance / TikTok -->\n                <tr data-category=\"social\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">TikTok (字节跳动海外)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">短视频信息流 + TikTok Shop</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-500/15 text-indigo-700 dark:text-indigo-400\">海外 ~16亿+ 月活</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">单列沉浸式算法 + 闭环电商</td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">~4%–5% (海外增速放缓)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">未公开 (海外投入大)</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>核心短视频劲敌，但地缘合规掣肘明显：</strong>Reels 已成功追平短视频时长份额；受欧美监管不确定性影响，大量品牌预算持续回流至更稳健的 Instagram 与 Facebook。\n                  </td>\n                </tr>\n\n                <!-- 行 5：Snap / Pinterest / X -->\n                <tr data-category=\"social\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Snap / Pinterest / X</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">垂直社交与视觉发现平台</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-400\">4亿–8亿 垂直月活</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-600 dark:text-slate-300\">中小规模机器学习模型</td>\n                  <td class=\"py-4 px-4 text-rose-600 dark:text-rose-400 font-semibold\">合计 &lt;2.5% (边缘化)</td>\n                  <td class=\"py-4 px-4 font-mono text-rose-600 dark:text-rose-400\">-5% 至 +8%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>算力军备竞赛下代差拉大：</strong>无力承担千亿美元级 AI 基础设施投入，广告主在测试后普遍将预算重新集中至算法精度更高的 Meta Advantage+。\n                  </td>\n                </tr>\n\n                <!-- 行 6：OpenAI (ChatGPT) -->\n                <tr data-category=\"ai_model\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">OpenAI (ChatGPT)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">GPT 系列闭源前沿模型 + 订阅/广告</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-teal-500/15 text-teal-700 dark:text-teal-400\">8亿+ 周活 · 独立 App 龙头</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">推理对话订阅 + 商业导流</td>\n                  <td class=\"py-4 px-4 font-semibold text-teal-600 dark:text-teal-400\">新兴 AI 入口广告试水</td>\n                  <td class=\"py-4 px-4 font-mono text-rose-600 dark:text-rose-400\">高算力亏损扩张期</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>消费级 AI 心智领跑者，但无自有社交分发护城河：</strong>Meta 凭借 WhatsApp/IG/FB 原生零成本分发使 Meta AI 迅速突破 10 亿月活，并用社交广告现金流全额反哺研发。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- 配套 Chart.js 横向条形图：营业利润率与每用户平均收入/盈利能力对比 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要数字媒体与社交平台营业利润率（Operating Margin）横向对比</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">Meta 凭借 35.4 亿用户规模效应与 AI 自动化投放，在承担每年百亿级 Reality Labs 研发投入后营业利润率仍高达 ~42.8%</p>\n            </div>\n            <span class=\"text-xs font-semibold text-metablue-600 dark:text-metablue-400 bg-metablue-500/15 px-2.5 py-1 rounded\">应用家族单体营业利润率更超 51%</span>\n          </div>\n          <div class=\"relative h-60 w-full\">\n            <canvas id=\"compMarginChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：千亿级 CapEx 周期下的强现金流自造血与估值锚点</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">远期 P/E ~21.5x · ROIC &gt;32%（全球顶级现金流机器）</span>\n        </div>\n\n        <!-- 1. 财务健康度四大硬核指标卡 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-metablue-600 dark:text-metablue-400 uppercase\">Gross Margin</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">81.2%</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              软件与数字广告商业模式赋予极高毛利率；尽管 AI 数据中心折旧攀升，毛利率仍稳居 80% 以上黄金线。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-sky-600 dark:text-sky-400 uppercase\">Operating Profit</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$105.5B</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              FY2026E 全年营业利润突破千亿美元（营业利润率 ~42.8%），其中核心应用家族（FoA）营业利润率高达 51%+。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">OCF & CapEx Cycle</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$118.0B</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              全年经营现金流（OCF）近 $1,200 亿，完全依靠内生造血即可覆盖 ~$125B AI 算力与定制 MTIA 芯片资本开支。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Balance Sheet & Buyback</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$70B+ 现金</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              资产负债表极为稳健，常态化季度股息发放叠加百亿美元级股票回购授权，持续增厚长期每股收益（EPS）。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 交互式 Chart.js 财务与估值演进双轴图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2022–FY2027E 营收/营业利润复利扩张与远期 P/E 估值走势</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">2023“效率年”后盈利重回高速通道，当前 ~21.5x 远期 P/E 兼具 18%–22% 营收增速，性价比凸显</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-metablue-600 dark:text-metablue-400 bg-metablue-500/10 px-2.5 py-1 rounded\">远期 P/E ~21.5x (低于科技七巨头均值)</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"valEvolutionChart\"></canvas>\n          </div>\n        </div>\n\n        <!-- 3. 估值体系演进三阶段 + 华尔街多空分歧面板 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n          <div class=\"p-5 rounded-xl bg-white dark:bg-navy-900 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-slate-500\">STAGE 01 · 2022 隐私与元宇宙低谷</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-mono font-semibold\">10x–14x P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">ATT 冲击与盲目元宇宙开支折价期</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              苹果隐私政策削弱广告归因，叠加 Reality Labs 无节制烧钱，市场一度担忧社交广告增长见顶，给予历史最低折价倍数。\n            </p>\n          </div>\n\n          <div class=\"p-5 rounded-xl bg-white dark:bg-navy-900 border border-sky-500/30 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-sky-600 dark:text-sky-400\">STAGE 02 · 2023–2024 效率年与 Reels 逆袭</span>\n              <span class=\"px-2 py-0.5 rounded bg-sky-500/15 text-sky-700 dark:text-sky-300 text-[11px] font-mono font-semibold\">22x–26x P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">组织瘦身与 AI 推荐重估阶段</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              裁员提效推动营业利润率重返 40%+，Reels 商业化破百亿且 Advantage+ 验证 AI 变现能力，估值向科技蓝筹中枢修复。\n            </p>\n          </div>\n\n          <div class=\"p-5 rounded-xl bg-gradient-to-br from-metablue-500/10 to-teal-500/10 border border-metablue-500/40 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-metablue-600 dark:text-metablue-400\">STAGE 03 · 2026 年底当前视角</span>\n              <span class=\"px-2 py-0.5 rounded bg-metablue-500/20 text-metablue-700 dark:text-metablue-300 text-[11px] font-mono font-semibold\">~21.5x Fwd P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">消费级 AI 超级平台与智能眼镜期权定价</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              市场对千亿 CapEx 短期自由现金流（FCF）压缩已有充分定价（~21.5x Fwd P/E），一旦 2027 年 CapEx 增速放缓且 AI 新业务变现加速，有望迎来估值上移。\n            </p>\n          </div>\n        </div>\n\n        <!-- 华尔街多空分歧对比 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          <div class=\"bg-sky-50/70 dark:bg-sky-950/20 rounded-2xl p-6 border border-sky-200 dark:border-sky-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-metablue-700 dark:text-metablue-400 text-base\">多头核心论点 (Bull Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-metablue-500/15 text-metablue-700 dark:text-metablue-300\">AI 变现确定性最高</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-metablue-600 font-bold\">✓</span><span><strong>唯一用真实利润证明 AI ROI 的应用巨头：</strong>每一美元算力投入都通过 GEM 推荐与 Advantage+ 转化为广告主可量化的订单转化。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-metablue-600 font-bold\">✓</span><span><strong>三大未充分变现的“十亿级金矿”：</strong>WhatsApp 商业 AI 代理、Threads 全球广告及 Meta AI 搜索信息流商业化均处于放量初期。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-metablue-600 font-bold\">✓</span><span><strong>智能眼镜定义下一代计算终端：</strong>Ray-Ban Meta 率先跑通大众消费级智能眼镜商业模式，有望摆脱苹果 iOS 生态抽成与限制。</span></li>\n            </ul>\n          </div>\n\n          <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">千亿 CapEx 折旧压力</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>千亿美元级 CapEx 推高未来折旧费用：</strong>2026–2027 年连续超 $120B–$140B 基础设施支出，将在未来 3–5 年转化为沉重折旧，阶段性压制利润率弹性。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>Reality Labs 长期经营亏损拖累：</strong>尽管 AI 眼镜热销，但底层 AR/VR 光学与操作系统研发每年仍带来 $17B–$19B 营业亏损。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>宏观消费周期与欧洲 DSA 监管罚款：</strong>全球零售与跨境电商广告主预算对宏观利率及欧美数据隐私监管高度敏感。</span></li>\n            </ul>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策与风险配置框架 (Investment Decision & Risk)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-metablue-600 dark:text-metablue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景估值推演与风控纪律</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：AI 应用层核心底仓 · 紧盯 18x–22x 估值锚点</span>\n        </div>\n\n        <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 牛市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-metablue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-metablue-500/15 text-metablue-600 dark:text-metablue-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                <span class=\"font-mono text-xs font-bold text-metablue-600 dark:text-metablue-400\">概率：30%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：26x – 28x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>GEM 推荐算法推动 FY27E 营收超预期突破 $305B+，WhatsApp AI 客服与 Threads 商业化贡献超 $15B 增量，AI 眼镜年出货破 1,500 万副，市场重估其端侧 AI 平台地位。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-metablue-600 dark:text-metablue-400\">\n              潜在上行空间：+35% 至 +45%（业绩+估值双升）\n            </div>\n          </div>\n\n          <!-- 基准情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-teal-500/15 text-teal-600 dark:text-teal-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                <span class=\"font-mono text-xs font-bold text-teal-600 dark:text-teal-400\">概率：50%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：22x – 24x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>FY27E 营收稳健兑现 ~$292B 共识预期（+18.5% YoY），营业利润率克服折旧攀升稳守 41%–43%，自由现金流随 CapEx 增速趋缓显著回升。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-teal-600 dark:text-teal-400\">\n              潜在上行空间：+18% 至 +25%（EPS 复利驱动）\n            </div>\n          </div>\n\n          <!-- 熊市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守估值：16x – 17x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>全球宏观消费走弱导致数字广告增速放缓至 10% 以下，而 2027 年基础设施 CapEx 仍维持 $140B+ 高位，折旧激增拉低营业利润率至 36% 左右。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n              潜在下行回撤：-15% 至 -20%（受 $70B 现金与回购托底）\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. 四大核心风险矩阵 -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构对冲缓释策略</h3>\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 千亿资本开支与折旧爬坡风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">AI 基础设施投入产出比（ROI）与自由现金流承压</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                公司持续大幅上调 AI 数据中心及自研 MTIA 芯片资本开支，若新业务（Meta AI、WhatsApp 商业化）变现速度滞后于折旧增长速度，将短期压制自由现金流与市场估值倍数。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 全球反垄断与数字隐私监管风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">欧盟 DMA/DSA 罚款及青少年网络安全立法制约</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                欧盟委员会对“付费或同意”个性化广告模式的严苛审查，以及欧美多国对青少年社交媒体使用时长与推荐算法的合规限制，可能抬高合规成本并限制部分定向广告精度。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 宏观经济与跨境广告主周期波动</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">电商、消费品与跨境出海广告投放弹性变化</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                全球电商与消费品牌占据 Meta 广告大盘核心份额，若关税政策变动或消费信贷收紧导致广告主削减获客预算，将直接传导至广告竞价（CPM）增速。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 新一代 AI 交互入口竞争风险</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">独立 AI 原生代理与 Apple Intelligence 生态竞争</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                若用户日常信息检索与消费决策加速向系统级 OS 代理（如苹果 iOS 底层 AI）或第三方原生 Agent 迁移，可能分流部分传统社交信息流浏览时长。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 机构级仓位配置建议 -->\n        <div class=\"bg-gradient-to-r from-navy-900 to-[#081F44] rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n          <h3 class=\"text-base font-bold text-metablue-400 mb-4 flex items-center space-x-2\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n            <span>机构级投资组合仓位配置与交易纪律建议</span>\n          </h3>\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-white mb-1\">1. AI 应用层核心底仓（Core Holding）</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                与硬件算力霸主 NVIDIA 形成完美“软硬互补”：建议作为科技组合中<strong>AI 应用层与数字广告变现的第一核心底仓（超配）</strong>，分享 AI 提效带来的内生现金流复利。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-metablue-400 mb-1\">2. 财报 CapEx 指引回调买点（18x–21x P/E）</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                历史经验表明，市场常在季报公布上调 CapEx 指引时因短期 FCF 担忧出现脉冲式回调，<strong>当远期 P/E 回落至 18x–20x 区间时是极具胜率的逆向加仓窗口</strong>。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-teal-400 mb-1\">3. 算力基建与端侧光学联动对冲</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                Meta 千亿美元级 CapEx 直接转化为上游 AI 芯片与高速光互联订单，组合中与上游算力硬件龙头形成天然的资金循环对冲，平滑单季 CapEx 波动影响。\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n      ========================================================= -->\n      <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n          </div>\n          <div class=\"flex items-center space-x-2 no-print\">\n            <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-metablue-500/15 text-metablue-600 dark:text-metablue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n            <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n            点击勾选机构季报追踪已验证达标的指标（状态自动本地保存），用高频运营指标动态验证 AI 变现飞轮与资本开支效率：\n          </p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n            <!-- KPI 1 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"meta-kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0668E1] focus:ring-metablue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 广告展示量（Impressions）与单价（Price per Ad）双升</span>\n                  <span class=\"text-[11px] font-mono text-metablue-600 dark:text-metablue-400 font-semibold shrink-0\">核心引擎锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  验证展示量同比保持 10%–13% 稳健扩张，同时单条广告均价（CPM）因 AI 转化率提升维持 +8%–11% 正向增长。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 2 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"meta-kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0668E1] focus:ring-metablue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 家族日活跃用户（DAP）稳步突破 35.4 亿并保持增速</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">流量基本盘</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪全球 DAP 同比保持 5%–6% 增长，重点关注欧美成熟市场年轻用户群在 Instagram Reels 与 Threads 的使用时长变化。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 3 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"meta-kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0668E1] focus:ring-metablue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 应用家族“其他收入”（WhatsApp 商业化）增速 &gt;45%</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">第二增长极</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测 WhatsApp 商业消息付费 API 及企业 AI 客服代理收入放量节奏，验证非传统展示广告的增量商业化空间。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 4 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"meta-kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0668E1] focus:ring-metablue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 合并营业利润率是否稳守 41%–43% 黄金区间</span>\n                  <span class=\"text-[11px] font-mono text-sky-600 dark:text-sky-400 font-semibold shrink-0\">盈利韧性锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查在数据中心折旧费用同比大幅上升的背景下，公司能否通过自研 MTIA 推理芯片降本及人均产出提升稳住 41%+ 营业利润率。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 5 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"meta-kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0668E1] focus:ring-metablue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 年度资本开支（CapEx）指引边际变化与 FCF 转化</span>\n                  <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">估值敏感指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  关注管理层对 2027 年基础设施 CapEx 增速是否进入温和放缓期（Deceleration），从而释放百亿美元级自由现金流弹性。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 6 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"meta-kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0668E1] focus:ring-metablue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. Reality Labs 营收增速（AI 眼镜放量）与亏损收窄信号</span>\n                  <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">端侧期权验证</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪 Ray-Ban Meta 等智能眼镜季度营收贡献是否持续实现 40%+ 同比增长，以及分部亏损率是否见顶回落。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>Meta Platforms (NASDAQ: META) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：FY2025 财报及 2026 年 11 月市场一致预期 (FY26E / FY27E)</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、全球数字广告与端侧穿戴供应链调研及市场一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的 FY2026E/FY2027E 营收预测、广告转化率测算、三情景估值模型及概率分布均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换（同步刷新所有 Chart.js 图表）\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与左侧导航滚动联动高亮\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-metablue-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-metablue-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. 同行竞争格局矩阵筛选器\n    // ==========================================\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-metablue-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        } else {\n          btn.classList.remove('bg-metablue-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category;\n        if (category === 'all' || rowCat === 'core' || rowCat === category) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    // ==========================================\n    // 5. KPI 核查清单状态持久化与计数更新\n    // ==========================================\n    const KPI_STORAGE_KEY = 'meta_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    // ==========================================\n    // 6. Chart.js 数据可视化初始化与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'evolution';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // 视图 A：FY2022–FY2027E 分部营收演进（堆叠柱状图）\n      const evoConfig = {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n          datasets: [\n            {\n              label: '应用家族广告 (FoA Advertising)',\n              data: [113.6, 131.9, 160.6, 195.8, 239.5, 282.5],\n              backgroundColor: '#0668E1',\n              borderRadius: 4,\n            },\n            {\n              label: '应用家族其他 (WhatsApp 商业/订阅)',\n              data: [0.8, 1.1, 1.7, 2.4, 3.0, 4.2],\n              backgroundColor: '#06B6D4',\n              borderRadius: 4,\n            },\n            {\n              label: 'Reality Labs (AI 智能眼镜与 XR)',\n              data: [2.2, 1.9, 2.1, 2.8, 4.0, 5.3],\n              backgroundColor: '#6366F1',\n              borderRadius: 4,\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              stacked: true,\n              max: 320,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            }\n          }\n        }\n      };\n\n      // 视图 B：FY2026E 营收区域分布与增量驱动拆分（横向柱状图）\n      const splitConfig = {\n        type: 'bar',\n        data: {\n          labels: [\n            '区域：北美市场 (US & Canada)',\n            '区域：欧洲市场 (Europe)',\n            '区域：亚太市场 (Asia-Pacific)',\n            '区域：世界其他地区 (Rest of World)',\n            '引擎：Advantage+ AI 自动化年化流水'\n          ],\n          datasets: [\n            {\n              label: 'FY2026E 营收/流水规模 ($B)',\n              data: [108.5, 58.2, 50.8, 29.0, 68.0],\n              backgroundColor: [\n                '#0668E1',\n                '#3B82F6',\n                '#06B6D4',\n                '#10B981',\n                '#6366F1'\n              ],\n              borderRadius: 6,\n              barThickness: 26\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `规模: $${ctx.parsed.x}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 130,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnEvo = document.getElementById('btn-chart-evo');\n      const btnSplit = document.getElementById('btn-chart-split');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'evolution') {\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-metablue-600 dark:text-metablue-400 shadow-sm transition';\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'FY2022–FY2027E 分部营收演进与广告复利加速';\n        subEl.textContent = '应用家族营收从 $114.5B 跃升至 FY26E $242.5B，Reality Labs 在 AI 眼镜带动下重回高增';\n      } else {\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-metablue-600 dark:text-metablue-400 shadow-sm transition';\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'FY2026E 全球区域营收分布与 AI 自动化广告体量';\n        subEl.textContent = '北美稳居核心压舱石，亚太与新兴市场保持高双位数扩张，Advantage+ 流水破 $68B';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            '真实社交网络效应 (35.4亿 DAP)',\n            '第一方闭环行为与意图数据',\n            'AI 推荐与广告 ROAS 转化力',\n            '千万级长尾广告主生态黏性',\n            '消费级 AI 入口与端侧眼镜卡位'\n          ],\n          datasets: [\n            {\n              label: 'Meta Platforms (META)',\n              data: [9.9, 9.5, 9.7, 9.8, 9.4],\n              borderColor: '#0668E1',\n              backgroundColor: 'rgba(6, 104, 225, 0.22)',\n              pointBackgroundColor: '#38BDF8',\n              borderWidth: 2.5\n            },\n            {\n              label: 'Alphabet (Google / YouTube)',\n              data: [7.6, 9.6, 9.4, 9.5, 8.8],\n              borderColor: '#10B981',\n              backgroundColor: 'rgba(16, 185, 129, 0.14)',\n              pointBackgroundColor: '#10B981',\n              borderWidth: 1.8\n            },\n            {\n              label: 'TikTok / Snap 等社交竞品',\n              data: [7.8, 7.5, 7.6, 6.8, 6.2],\n              borderColor: '#94A3B8',\n              backgroundColor: 'rgba(148, 163, 184, 0.12)',\n              pointBackgroundColor: '#94A3B8',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initCompMarginChart() {\n      const ctx = document.getElementById('compMarginChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (compMarginChartInstance) compMarginChartInstance.destroy();\n      compMarginChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: [\n            'Meta Platforms (META · 社交广告帝国)',\n            'Alphabet (GOOGL · 搜索与 YouTube)',\n            'Spotify / 流媒体音频平台',\n            'Pinterest (PINS · 视觉发现社交)',\n            'Snap (SNAP · 即时影像社交)'\n          ],\n          datasets: [{\n            label: '营业利润率 Operating Margin (%)',\n            data: [42.8, 33.2, 11.5, 7.8, -6.5],\n            backgroundColor: [\n              '#0668E1',\n              '#3B82F6',\n              '#06B6D4',\n              '#64748B',\n              '#F43F5E'\n            ],\n            borderRadius: 6,\n            barThickness: 22\n          }]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `营业利润率: ${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              min: -10,\n              max: 55,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initValEvolutionChart() {\n      const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n      valEvolutionChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E', 'FY2027E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '全年总营收 ($B)',\n              data: [116.6, 134.9, 164.5, 201.0, 246.5, 292.0],\n              backgroundColor: 'rgba(6, 104, 225, 0.85)',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'bar',\n              label: '全年营业利润 ($B)',\n              data: [28.9, 46.8, 69.4, 86.2, 105.5, 126.5],\n              backgroundColor: 'rgba(6, 182, 212, 0.85)',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '远期市盈率 Forward P/E (x)',\n              data: [13.5, 22.8, 25.4, 23.8, 21.5, 18.2],\n              borderColor: '#F59E0B',\n              backgroundColor: '#F59E0B',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                  : `${ctx.dataset.label}: ${ctx.parsed.y}x`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 330,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: 0,\n              max: 35,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + 'x' }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initCompMarginChart();\n      initValEvolutionChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      initBizChart();\n      initRadarChart();\n      initCompMarginChart();\n      initValEvolutionChart();\n    });\n  </script>\n</body>\n</html>\n"};
